Translate("ruRU", "dustwallow-marsh", {
	title = "Пылевые топи",
	aliases = { "Пылевые топи", "Пылевое болото" },
	sections = {
		{
			title = "Обзор",
			text = [=[Пылевые топи — затопленный край черной воды, тростника и тумана на восточном побережье {link:kalimdor}Калимдора{/link}, к югу от {link:the-barrens}Степей{/link}. Его дороги тонут в грязи, его деревья гниют на корню, и в каждой заводи лежат кроколиски. На восточном его краю, на острове в заливе, стоит белый {link:theramore-isle}город Терамор{/link} — убежище людей, пересекших море после падения {link:lordaeron}Лордерона{/link}. На западе {link:ogres}огр{/link}ы клана Каменного Молота теснятся в деревне из хижин среди тростников. А на дальнем юге, где трясина сменяется выжженным камнем, в Драконьих топях гнездятся черные драконы.]=],
