			title = "История",
			text = [=[• {b}Исход.{/b} {link:jaina-proudmoore}Джайна Праудмур{/link} увела выживших из {link:lordaeron}Лордерон{/link}а на запад, через море, в {link:kalimdor}Калимдор{/link}.
• {b}{link:theramore-isle}Терамор{/link}.{/b} После битвы у горы Хиджал беженцы построили свой город на острове, и многие из морских пехотинцев адмирала вступили в его стражу.
• {b}Война адмирала.{/b} {link:daelin-proudmoore}Делин Праудмур{/link} пошел войной на Орду и пал у Терамора.
• {b}Клан Каменного Молота.{/b} {link:rexxar}Рексар{/link} какое-то время возглавлял клан. Когда он ушел, от его имени правил {link:overlord-mok-morokk}Мок'Морокк{/link}.]=],
		},
		{
			title = "Предания топей",
			text = [=[• Стража {link:theramore-isle}Терамор{/link}а носит знак — золотой якорь на белом. Это знак города.
• Отшельница {link:tabetha}Табета{/link} держит хижину в глубине топей, и ее разыскивают маги и чернокнижники.
• На острове к югу от Терамора живет рыбак, который говорит, что рыбалка никогда особо его не радовала.]=],
		},
	},
})

Translate("ruRU", "theramore-isle", {
	title = "Остров Терамор",
	aliases = { "Терамор", "город Терамор" },
	sections = {
		{
			title = "Обзор",
			text = [=[Терамор — город леди {link:jaina-proudmoore}Джайны Праудмур{/link}, возведенный на острове в заливе Пылевых топей. Его белые стены и синие крыши дают приют беженцам из {link:lordaeron}Лордерон{/link}а и морским пехотинцам {link:kul-tiras}Кул Тирас{/link}а, оставшимся рядом со своей госпожой. В Цитадели размещаются его казармы и офицеры, а высокая башня служит резиденцией самой леди. От его причалов корабли ходят через море в {link:menethil-harbor}Гавань Менетилов{/link}. Терамор — город {link:alliance}Альянса{/link}, но его госпожа хранит мир с {link:horde}Ордой{/link}. Не все, кто живет в его стенах, любят этот мир.]=],
		},
	},
})

Translate("ruRU", "brackenwall-village", {
	title = "Деревня Гиблотопь",
	aliases = { "Гиблотопь" },
	sections = {
		{
			title = "Обзор",
			text = [=[Деревня Гиблотопь — лагерь Орды из хижин и частоколов в западной части топей, близ дороги в {link:burning-steppes}Степи{/link}. Здесь живут {link:ogres}огр{/link}ы клана Каменного Молота, бежавшие сюда, когда черные драконы сожгли их старую деревню на юге. {link:overlord-mok-morokk}Властитель Мок'Морокк{/link} правит ограми из ее середины и уходить не желает. Здесь же держат свои посты агенты-{link:orcs}орк{/link}и Орды: глава лазутчиков, который следит за {link:theramore-isle}Терамор{/link}ом, и воин, который ищет правду о сожжении таверны {link:shady-rest-inn}«Последний привал»{/link}.]=],
		},
	},
})

Translate("ruRU", "stonemaul-ruins", {
	title = "Руины Деревни Каменного Молота",
	aliases = { "Деревня Каменного Молота" },
	sections = {
		{
			title = "Обзор",
			text = [=[Руины Деревни Каменного Молота были домом {link:ogres}огр{/link}ов клана Каменного Молота, пока не пришли черные драконы. Теперь ее сожженные хижины держат дракониды выводка Огненной Гривы и стаи опаляющих дракончиков, а соседняя пещера, которую зовут Огненным логовом, пылает их огнем. Огры бежали так быстро, что их властитель оставил там свой грог, свой нюхательный табак и свой ларец. Старый {link:tharg}Тарг{/link} до сих пор зовет эти руины домом и мечтает отбить их. {link:draz-zilb}Драз'Зилб{/link} полагает, что драконы пришли ради некой цели, большей, чем изгнание небольшой шайки огров.]=],
		},
	},
})

Translate("ruRU", "wyrmbog", {
	title = "Драконьи топи",
	aliases = { "Драконьи топи", "Земля Драконов" },
	sections = {
		{
			title = "Обзор",
			text = [=[Драконьи топи — дальний юг Пылевых топей, где болото уступает место выжженному камню. Здесь гнездятся черные драконы. Яйца, которые отложила {link:onyxia}Ониксия{/link}, разбросаны по трясине, что зовется Землей Драконов, и ее выводок стережет их. В собственной пещере обитает древний дракон {link:emberstrife}Огнебор{/link}. В глубине топей открывается пещера — {link:onyxias-lair}Логово Ониксии{/link}, где, как говорят, мать выводка спит на своих сокровищах. Немногие из тех, кто идет туда, возвращаются, чтобы рассказать об этом.]=],
		},
	},
})

Translate("ruRU", "shady-rest-inn", {
	title = "Таверна «Последний привал»",
	aliases = { "«Последний привал»" },
	sections = {
		{
			title = "Обзор",
			text = [=[Таверна «Последний привал» стояла на западной дороге Пылевых топей, близ границы Степей. {link:smiling-jim}Джеймс Хиал{/link} построил ее, чтобы дать путникам надежную крышу, и какое-то время дела шли хорошо. Потом дороги вышли из-под власти {link:theramore-isle}Терамор{/link}а, а хозяин не пожелал уйти. Теперь остались лишь дымящийся остов и осыпающаяся печная труба. Среди пепла лежат почерневший щит, значок Терамора и ряды следов копыт в грязи. Жена и ребенок хозяина погибли в огне.]=],
		},
	},
})

Translate("ruRU", "swamplight-manor", {
	title = "Сторожка «Болотный огонек»",
	sections = {
		{
			title = "Обзор",
			text = [=[Сторожка «Болотный огонек» — одинокий дом на Ведьмином холме, на севере топей. Его единственный жилец — странный человек, {link:swamp-eye-jarl}«Болотный Глаз» Ярл{/link}: он варит похлебки из лягушачьих лапок и пьет сок паучьих глаз. Он держится особняком, и большинство путников это вполне устраивает. Всего в нескольких шагах от его двери рыхлая земля когда-то скрывала руку и голову убитого лазутчика-{link:orcs}орк{/link}а. Ни одна летопись не говорит, кто построил этот дом и что сталось с его первыми хозяевами.]=],
		},
	},
})

Translate("ruRU", "sentry-point", {
	title = "Сторожевой пост",
	sections = {
		{
			title = "Обзор",
			text = [=[Сторожевой пост — первая башня {link:theramore-isle}Терамор{/link}а на дороге в топи, на побережье к северо-западу от города. Ее держат капитан и небольшой отряд стражников. Она стережет насыпь, ведущую к Терамору, и болото за ней. Дальше дорога идет на запад, в земли, которые Терамору больше не подвластны. Говорили, что именно здесь нес службу солдат {link:private-hendel}Хендель{/link}, и именно здесь начались его поиски.]=],
		},
	},
})

Translate("ruRU", "north-point-tower", {
	title = "Северная башня",
	aliases = { "Северная башня" },
	sections = {
		{
			title = "Обзор",
			text = [=[Северная башня — застава {link:theramore-isle}Терамор{/link}а в северной части топей, на дороге, что идет на запад, к Степям. {link:sentinels}Часовые{/link} охраняют палатки вдоль дороги, где лазутчики Терамора отдыхают между вылазками. Отсюда лазутчики пробираются в тростники, чтобы следить за Деревней {link:brackenwall-village}Гиблотопь{/link}. В окрестностях охотятся ящеры и кроколиски, и часовые не сводят глаз с тростников. {link:private-hendel}Рядовой Хендель{/link} стоял на страже этого лагеря, а {link:horde}Орда{/link} послала собственных охотников, чтобы очистить свой порог от лазутчиков.]=],
		},
	},
})

Translate("ruRU", "lost-point", {
	title = "Разрушенная башня",
	sections = {
		{
			title = "Обзор",
			text = [=[Разрушенная башня — брошенная башня {link:theramore-isle}Терамор{/link}а к юго-востоку от таверны {link:shady-rest-inn}«Последний привал»{/link}. Терамор больше не мог ее удерживать, и ее забрали себе дезертиры. Это бывшие солдаты города, и возглавляет их {link:balos-jacken}Балос Джекен{/link}. Они хотят лишь одного — чтобы о них забыли, но о топях они знают больше, чем стражники, некогда служившие рядом с ними. Капитан Ваймс послал разобраться с ними лейтенанта Колдуэлла.]=],
		},
	},
})

Translate("ruRU", "darkmist-cavern", {
	title = "Мглистая пещера",
	sections = {
		{
			title = "Обзор",
			text = [=[Мглистая пещера открывается на северо-западе топей. Это логово {link:ogres}огр{/link}омных пауков: отшельников, шелкопрядов и вдов Мглистой пещеры, которые ткут свои сети поперек ее устья. Путники спешат миновать ее. У отшельника, «Болотного Глаза» {link:swamp-eye-jarl}Ярл{/link}а, иной взгляд на это место. Он ценит глаза здешних пауков и любит, чтобы они были целыми. Пауков ли назвали по пещере или пещеру по паукам — этого не может сказать даже Ярл.]=],
		},
	},
})

Translate("ruRU", "alcaz-island", {
	title = "Остров Алькац",
	aliases = { "Алькац" },
	sections = {
		{
			title = "Обзор",
			text = [=[Остров Алькац лежит у северо-восточного побережья Пылевых топей, через воду от {link:theramore-isle}Терамор{/link}а. Его держат {link:naga}наги{/link} Страшаз: воины, сирены, колдуньи и {link:ogres}огр{/link}омные гидры, что свиваются кольцами на мелководье. Никто в Тераморе не говорит о том, почему наги подошли так близко к городу и что они стерегут на своем острове. Гидры наг охотятся в водах между островом и северным берегом, и моряки залива держатся от них подальше.]=],
		},
	},
})

