		{ text = "«Черный щит»" },
		{ text = "«Лейтенант {link:paval-reethe}Павал Рит{/link}»" },
		{ text = "«Лейтенант {link:paval-reethe}Павал Рит{/link}»" },
		{ text = "«{link:humans}Люди{/link} адмирала»" },
		{ text = "«Дезертиры»" },
